/**
 * Parser and types for the committed `frontend/public/table/shells.json`.
 *
 * The manifest is generated by `tools/render/bake_shells.py` and validated by
 * `tools/render/scripts/check-shells.mjs`. This module trusts the committed
 * values but rejects a structurally wrong or drifted document at startup,
 * because every draw position and glyph placement is derived from it.
 *
 * Coordinates are CSS px of the @1x texture with a top-left origin. The @2x
 * texture is exactly `pixelRatio` times the resolution, so the atlas can draw
 * at 2x without changing logical layout.
 *
 * The shell catalogue is not hard-coded here: the atlas consumes the manifest,
 * and the Phase 2 face-up subset lives in `tiles.ts`.
 */
import { isFaceUpShellId } from './tiles';
import type { FaceUpShellId } from './tiles';

/** `[x, y]` in @1x CSS px, texture top-left origin. */
export type PointPx = readonly [number, number];

/** A shell's visible face plate, in face-local corner order. */
export type FaceQuad = readonly [PointPx, PointPx, PointPx, PointPx];

export interface ShellPadding {
  readonly top: number;
  readonly right: number;
  readonly bottom: number;
  readonly left: number;
}

export interface ShellPose {
  readonly rotateXDeg: number;
  readonly rotateYDeg: number;
  readonly rotateZDeg: number;
}

/**
 * The hard shadow footprint a shell casts, in @1x px relative to the tile's
 * grid anchor. The group-shadow pass draws this rotated rounded rectangle at
 * alpha 1, merges overlaps, then blurs the union once (§10.12).
 */
export interface ShadowShape {
  readonly centrePx: PointPx;
  readonly halfPx: PointPx;
  readonly radiusPx: number;
  readonly angleDeg: number;
  readonly sigmaPx1x: number;
  readonly coreAlpha: number;
  readonly colorHex: string;
  readonly lying: boolean;
}

/**
 * The camera-slot metadata a fan row needs. `offsetUnits` is the slot's
 * lateral offset from the row centre in tile widths, so the layout engine can
 * derive the fan origin from the manifest instead of hard-coding slot tables.
 */
export interface SlotMeta {
  readonly kind: string;
  /** Row/draw/index; null for the drawn tile's slot. */
  readonly index: number | null;
  readonly offsetUnits: number;
  readonly lateralOffsetUnits: number;
  readonly distanceUnits: number;
  readonly angleDeg: number;
  readonly faceUp: boolean;
}

/** A front/back wall slot record. Front is the human side, back the far side. */
export interface WallSlotMeta {
  readonly wall: string;
  readonly index: number | null;
  readonly offsetUnits: number;
  readonly lateralOffsetUnits: number;
  readonly distanceUnits: number;
  readonly angleDeg: number;
  readonly faceUp: boolean;
}

export interface ShellStats {
  readonly textureFile: string;
  readonly textureFile2x: string;
  readonly texWidth: number;
  readonly texHeight: number;
  readonly anchorX: number;
  readonly anchorY: number;
  readonly advanceWidth: number;
  readonly advanceHeight: number;
  readonly padding: ShellPadding;
  /**
   * The glyph's desired on-screen rotation: 0 upright, 90 counter-clockwise,
   * 180 upside down, 270 clockwise. It is not the faceQuad's own rotation for
   * every shell: the side-wall dora shells have a 90-degree quad but a 0-degree
   * glyph, and the back-wall dora shells have an upright quad but a 180-degree
   * glyph. `glyphRotationDegFor` subtracts the quad rotation to get the extra
   * rotation to apply inside the face plate.
   */
  readonly faceRotationDeg: 0 | 90 | 180 | 270;
  readonly faceQuad: FaceQuad;
  readonly faceQuadOrder: string;
  /** Projected tile axis steps in @1x px; use these for tight grids. */
  readonly gridStepPx: { readonly x: PointPx; readonly y: PointPx };
  /** Upper-tier offset on a wall stack; present on the wall shells. */
  readonly stackCount?: number;
  readonly stackStepPx?: PointPx;
  /** The human hand's slot camera record. */
  readonly handSlot?: SlotMeta;
  /** The top hand's slot camera record. */
  readonly topHandSlot?: SlotMeta;
  /** A front/back wall slot record. */
  readonly wallSlot?: WallSlotMeta;
  /** The hard footprint of the group shadow; every committed shell has one. */
  readonly shadowShape: ShadowShape;
  readonly projection: string;
  readonly pose: ShellPose;
  /** Authoritative glyph/blue-back switch. False on the wall and top hand. */
  readonly faceUp: boolean;
  /**
   * The bake's measured RGB sample at the middle of the face plate (`@1x`,
   * 0-255). Task 5A uses it to tone-match the carved ivory so the relief
   * highlights stay relative to the shell body they sit on.
   */
  readonly faceSampleRgb?: readonly [number, number, number];
}

export interface ShellsManifest {
  readonly version: number;
  readonly generatedBy: string;
  readonly pixelRatio: number;
  readonly shells: Readonly<Record<string, ShellStats>>;
}

function fail(message: string): never {
  throw new Error(`shells.json: ${message}`);
}

function finite(value: unknown, field: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) fail(`${field} must be a finite number`);
  return value;
}

function point(value: unknown, field: string): PointPx {
  if (
    !Array.isArray(value) ||
    value.length !== 2 ||
    value.some((entry) => typeof entry !== 'number' || !Number.isFinite(entry))
  ) {
    fail(`${field} must be [x, y]`);
  }
  return [value[0], value[1]] as const;
}

function positive(value: unknown, field: string): number {
  const number = finite(value, field);
  if (number <= 0) fail(`${field} must be positive`);
  return number;
}

function nonNegative(value: unknown, field: string): number {
  const number = finite(value, field);
  if (number < 0) fail(`${field} must be zero or positive`);
  return number;
}

function parseRotation(value: unknown, field: string): 0 | 90 | 180 | 270 {
  if (value !== 0 && value !== 90 && value !== 180 && value !== 270) {
    fail(`${field} must be 0, 90, 180 or 270`);
  }
  return value;
}

function parseQuad(value: unknown, field: string): FaceQuad {
  if (!Array.isArray(value) || value.length !== 4) fail(`${field} must have four corners`);
  const corners = value.map((corner, index) => point(corner, `${field}[${index}]`));
  return [corners[0], corners[1], corners[2], corners[3]];
}

function objectOf(value: unknown, field: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    fail(`${field} must be an object`);
  }
  return value as Record<string, unknown>;
}

function parseShadowShape(value: unknown, field: string): ShadowShape {
  const shape = objectOf(value, field);
  if (typeof shape.colorHex !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(shape.colorHex)) {
    fail(`${field}.colorHex must be #rrggbb`);
  }
  if (typeof shape.lying !== 'boolean') fail(`${field}.lying must be a boolean`);
  const coreAlpha = finite(shape.coreAlpha, `${field}.coreAlpha`);
  if (coreAlpha < 0 || coreAlpha > 1) fail(`${field}.coreAlpha must be 0..1`);
  return {
    centrePx: point(shape.centrePx, `${field}.centrePx`),
    halfPx: point(shape.halfPx, `${field}.halfPx`),
    radiusPx: nonNegative(shape.radiusPx, `${field}.radiusPx`),
    angleDeg: finite(shape.angleDeg, `${field}.angleDeg`),
    sigmaPx1x: nonNegative(shape.sigmaPx1x, `${field}.sigmaPx1x`),
    coreAlpha,
    colorHex: shape.colorHex,
    lying: shape.lying,
  };
}

function parseSlotFields(slot: Record<string, unknown>, field: string) {
  if (typeof slot.faceUp !== 'boolean') fail(`${field}.faceUp must be a boolean`);
  let index: number | null = null;
  if (slot.index !== null && slot.index !== undefined) {
    const number = finite(slot.index, `${field}.index`);
    if (!Number.isInteger(number) || number < 0) fail(`${field}.index must be an integer`);
    index = number;
  }
  return {
    index,
    offsetUnits: finite(slot.offsetUnits, `${field}.offsetUnits`),
    lateralOffsetUnits: finite(slot.lateralOffsetUnits, `${field}.lateralOffsetUnits`),
    distanceUnits: positive(slot.distanceUnits, `${field}.distanceUnits`),
    angleDeg: finite(slot.angleDeg, `${field}.angleDeg`),
    faceUp: slot.faceUp,
  };
}

function parseSlot(value: unknown, field: string): SlotMeta {
  const slot = objectOf(value, field);
  if (typeof slot.kind !== 'string' || !slot.kind) fail(`${field}.kind must be a string`);
  return { kind: slot.kind, ...parseSlotFields(slot, field) };
}

function parseWallSlot(value: unknown, field: string): WallSlotMeta {
  const wall = objectOf(value, field);
  if (wall.wall !== 'front' && wall.wall !== 'back') {
    fail(`${field}.wall must be front or back`);
  }
  return { wall: wall.wall, ...parseSlotFields(wall, field) };
}

/** True when a shell shows its blue resin back, so no glyph belongs on it. */
export function isFaceDownShell(shell: ShellStats): boolean {
  return !shell.faceUp;
}

function normalizeDegrees(value: number): 0 | 90 | 180 | 270 {
  const wrapped = ((Math.round(value / 90) * 90) % 360 + 360) % 360;
  return wrapped as 0 | 90 | 180 | 270;
}

/** Normalize a multiple-of-90 angle to 0/90/180/270. */
export function normalizeRotationDeg(value: number): 0 | 90 | 180 | 270 {
  return normalizeDegrees(value);
}

/**
 * Screen rotation, in degrees counter-clockwise, that maps the glyph's own
 * top-left-to-top-right edge onto the faceQuad's first edge. 0 when the edge
 * points right, 90 when it points up, 180 when it points left, 270 when it
 * points down. The dominant component is used because a perspective face is a
 * trapezoid (the edge is not exactly axis-aligned).
 */
export function screenRotationOfQuad(quad: FaceQuad): 0 | 90 | 180 | 270 {
  const [topLeft, topRight] = quad;
  const dx = topRight[0] - topLeft[0];
  const dy = topRight[1] - topLeft[1];
  if (Math.abs(dx) >= Math.abs(dy)) return dx >= 0 ? 0 : 180;
  // Screen y grows downward. A top edge pointing up is a 90° CCW rotation.
  return dy < 0 ? 90 : 270;
}

/**
 * The extra rotation to apply to the glyph inside the face plate so its final
 * on-screen rotation equals `faceRotationDeg`. In the Phase 2 catalogue this is
 * always 0: the published quad already carries the rotation (90° CCW for
 * `shell_flat_sideways`). The back-wall dora shells publish 180 here, and the
 * side-wall dora shells 270, for the follow-up variant work.
 */
export function glyphRotationDegFor(shell: {
  readonly faceQuad: FaceQuad;
  readonly faceRotationDeg: 0 | 90 | 180 | 270;
}): 0 | 90 | 180 | 270 {
  return normalizeDegrees(shell.faceRotationDeg - screenRotationOfQuad(shell.faceQuad));
}

/**
 * The baked carve light rotation for a shell. The decal is lit in face-local
 * space, then the shell's quad rotates it on screen. To keep the carve light
 * top-left on screen, the decal is pre-rotated by the negative of the quad's
 * own rotation. `shell_flat_sideways` (quad 90°) therefore uses the 270° decal.
 */
export function decalLightRotationDegFor(shell: {
  readonly faceQuad: FaceQuad;
}): 0 | 90 | 180 | 270 {
  return normalizeDegrees(-screenRotationOfQuad(shell.faceQuad));
}

/**
 * The extra in-plate symbol rotation for a shell: the published face rotation
 * minus the quad's own rotation. It is 0 for every Phase 2 shell (the symbol
 * rides with the tile); the back-wall dora slots need 180 and the side-wall
 * dora slots 270.
 */
export function decalSymbolRotationDegFor(shell: {
  readonly faceQuad: FaceQuad;
  readonly faceRotationDeg: 0 | 90 | 180 | 270;
}): 0 | 90 | 180 | 270 {
  return normalizeDegrees(shell.faceRotationDeg - screenRotationOfQuad(shell.faceQuad));
}

function parseShell(id: string, raw: unknown): ShellStats {
  if (typeof raw !== 'object' || raw === null) fail(`${id} must be an object`);
  const shell = raw as Record<string, unknown>;
  const textureFile = shell.textureFile;
  const textureFile2x = shell.textureFile2x;
  if (typeof textureFile !== 'string' || !textureFile) fail(`${id}.textureFile must be a path`);
  if (typeof textureFile2x !== 'string' || !textureFile2x) {
    fail(`${id}.textureFile2x must be a path`);
  }
  const paddingRaw = shell.padding;
  if (typeof paddingRaw !== 'object' || paddingRaw === null) fail(`${id}.padding must be an object`);
  const padding = paddingRaw as Record<string, unknown>;
  const gridRaw = shell.gridStepPx;
  if (typeof gridRaw !== 'object' || gridRaw === null) fail(`${id}.gridStepPx must be an object`);
  const grid = gridRaw as Record<string, unknown>;
  const poseRaw = shell.pose;
  if (typeof poseRaw !== 'object' || poseRaw === null) fail(`${id}.pose must be an object`);
  const pose = poseRaw as Record<string, unknown>;
  if (typeof shell.faceUp !== 'boolean') fail(`${id}.faceUp must be a boolean`);

  let stackCount: number | undefined;
  let stackStepPx: PointPx | undefined;
  if (shell.stackStepPx !== undefined) {
    stackStepPx = point(shell.stackStepPx, `${id}.stackStepPx`);
    const count = positive(shell.stackCount, `${id}.stackCount`);
    if (!Number.isInteger(count)) fail(`${id}.stackCount must be an integer`);
    stackCount = count;
  }
  const handSlot =
    shell.handSlot === undefined ? undefined : parseSlot(shell.handSlot, `${id}.handSlot`);
  const topHandSlot =
    shell.topHandSlot === undefined
      ? undefined
      : parseSlot(shell.topHandSlot, `${id}.topHandSlot`);
  const wallSlot =
    shell.wallSlot === undefined ? undefined : parseWallSlot(shell.wallSlot, `${id}.wallSlot`);

  const measuredRaw =
    typeof shell.measured === 'object' && shell.measured !== null
      ? (shell.measured as Record<string, unknown>)
      : null;
  const sampleRaw = measuredRaw?.faceSampleRgb;
  let faceSampleRgb: readonly [number, number, number] | undefined;
  if (sampleRaw !== undefined) {
    if (!Array.isArray(sampleRaw) || sampleRaw.length !== 3) {
      fail(`${id}.measured.faceSampleRgb must be [r, g, b]`);
    }
    faceSampleRgb = [
      finite(sampleRaw[0], `${id}.measured.faceSampleRgb[0]`),
      finite(sampleRaw[1], `${id}.measured.faceSampleRgb[1]`),
      finite(sampleRaw[2], `${id}.measured.faceSampleRgb[2]`),
    ] as const;
  }

  const stats: ShellStats = {
    textureFile,
    textureFile2x,
    texWidth: positive(shell.texWidth, `${id}.texWidth`),
    texHeight: positive(shell.texHeight, `${id}.texHeight`),
    anchorX: nonNegative(shell.anchorX, `${id}.anchorX`),
    anchorY: nonNegative(shell.anchorY, `${id}.anchorY`),
    advanceWidth: positive(shell.advanceWidth, `${id}.advanceWidth`),
    advanceHeight: positive(shell.advanceHeight, `${id}.advanceHeight`),
    padding: {
      top: nonNegative(padding.top, `${id}.padding.top`),
      right: nonNegative(padding.right, `${id}.padding.right`),
      bottom: nonNegative(padding.bottom, `${id}.padding.bottom`),
      left: nonNegative(padding.left, `${id}.padding.left`),
    },
    faceRotationDeg: parseRotation(shell.faceRotationDeg, `${id}.faceRotationDeg`),
    faceQuad: parseQuad(shell.faceQuad, `${id}.faceQuad`),
    faceQuadOrder: typeof shell.faceQuadOrder === 'string' ? shell.faceQuadOrder : '',
    gridStepPx: {
      x: point(grid.x, `${id}.gridStepPx.x`),
      y: point(grid.y, `${id}.gridStepPx.y`),
    },
    ...(stackCount === undefined ? {} : { stackCount, stackStepPx }),
    ...(handSlot === undefined ? {} : { handSlot }),
    ...(topHandSlot === undefined ? {} : { topHandSlot }),
    ...(wallSlot === undefined ? {} : { wallSlot }),
    ...(faceSampleRgb === undefined ? {} : { faceSampleRgb }),
    shadowShape: parseShadowShape(shell.shadowShape, `${id}.shadowShape`),
    projection: typeof shell.projection === 'string' ? shell.projection : '',
    pose: {
      rotateXDeg: finite(pose.rotateXDeg, `${id}.pose.rotateXDeg`),
      rotateYDeg: finite(pose.rotateYDeg, `${id}.pose.rotateYDeg`),
      rotateZDeg: finite(pose.rotateZDeg, `${id}.pose.rotateZDeg`),
    },
    faceUp: shell.faceUp,
  };

  // The manifest's own invariants; a drift here would place every glyph wrong.
  if (
    stats.anchorX + stats.advanceWidth + stats.padding.right !== stats.texWidth ||
    stats.anchorX !== stats.padding.left
  ) {
    fail(`${id} horizontal anchor/advance/padding do not add up to texWidth`);
  }
  if (
    stats.anchorY + stats.advanceHeight + stats.padding.bottom !== stats.texHeight ||
    stats.anchorY !== stats.padding.top
  ) {
    fail(`${id} vertical anchor/advance/padding do not add up to texHeight`);
  }
  return stats;
}

/** Parse and validate a decoded `shells.json`. */
export function parseShellsManifest(raw: unknown): ShellsManifest {
  if (typeof raw !== 'object' || raw === null) fail('document must be an object');
  const doc = raw as Record<string, unknown>;
  if (doc.version !== 1) fail(`version must be 1, got ${String(doc.version)}`);
  const pixelRatio = positive(doc.pixelRatio, 'pixelRatio');
  if (pixelRatio !== 1 && pixelRatio !== 2) fail('pixelRatio must be 1 or 2');
  if (typeof doc.shells !== 'object' || doc.shells === null) fail('shells must be an object');
  const shellsRaw = doc.shells as Record<string, unknown>;
  const ids = Object.keys(shellsRaw);
  if (ids.length === 0) fail('shells must not be empty');

  const shells: Record<string, ShellStats> = {};
  for (const id of ids) {
    if (!id.startsWith('shell_')) fail(`unknown shell ${id}`);
    shells[id] = parseShell(id, shellsRaw[id]);
  }

  return {
    version: 1,
    generatedBy: typeof doc.generatedBy === 'string' ? doc.generatedBy : '',
    pixelRatio,
    shells,
  };
}

/** A typed accessor for a Phase 2 face-up shell record. */
export function faceUpShellStats(shells: ShellsManifest, id: FaceUpShellId): ShellStats {
  if (!isFaceUpShellId(id)) throw new Error(`${id} is not a Phase 2 face-up shell`);
  const shell = shells.shells[id];
  if (!shell) throw new Error(`shells.json has no ${id}`);
  return shell;
}
